[DataContractAttribute]
public class FMVehicleDataContract
{
    str _VIN;
    str _Make;
    str _Model;
    str _Mileage;
    str _Color;
    int _MPG;
    str _transmission;
    str _AssembledIn;
    str _CarFactsSummary;
    FMVehicleStatus _Status;
}

Method.Source:
public str CarFactsSummary(str carFactsSummary = _CarFactsSummary)
{
    _CarFactsSummary = carFactsSummary;
    return _CarFactsSummary;
}

[DataMemberAttribute]
public str Make(str make = _Make)
{
    _Make = make;
    return _Make;
}

[DataMemberAttribute]
public str Model(str model = _Model)
{
    _Model = model;
    return _Model;
}

public FMVehicleStatus Status(FMVehicleStatus status = _Status )
{
    _Status = status;
    return _Status;
}

[DataMemberAttribute]
public str VIN(str vin = _VIN)
{
    _VIN = vin;
    return _VIN;
}
